const src = $('Per Project').first().json;
const resp = $input.first().json;
const headers = resp.headers || {};
const total = parseInt(headers['x-pagination-total-count'] || headers['X-Pagination-Total-Count'] || '0', 10);
if (!total) {
  throw new Error('No total count header for ' + src.name + ' :: ' + JSON.stringify(headers).slice(0, 300));
}
const limit = 500;
const pageCount = Math.ceil(total / limit);
const out = [];
for (let p = 1; p <= pageCount; p++) {
  out.push({ json: { project_id: src.project_id, name: src.name, product: src.product, page: p, limit, total_keys: total } });
}
return out;

const src = $('Per Project').first().json;
const meta = $('Expand Pages').first().json;

const PSEUDO = new Set(['pst','ps','cus','pt_old']);
const empties = {};

function isEmpty(t) {
  if (t === null || t === undefined) return true;
  if (typeof t === 'string') {
    const s = t.trim();
    if (!s) return true;
    if (s.startsWith('{') || s.startsWith('[')) {
      try { return isEmpty(JSON.parse(s)); } catch (e) { return false; }
    }
    return false;
  }
  if (typeof t === 'object') {
    const vals = Object.values(t);
    if (!vals.length) return true;
    return vals.every(v => isEmpty(v));
  }
  return false;
}

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const keys = body.keys;
  if (!Array.isArray(keys)) throw new Error('No keys array for ' + src.name);
  for (const k of keys) {
    const trs = Array.isArray(k.translations) ? k.translations : [];
    const emptyLocales = [];
    for (const tr of trs) {
      const iso = tr.language_iso;
      if (!iso || PSEUDO.has(iso)) continue;
      if (isEmpty(tr.translation)) emptyLocales.push(iso);
    }
    if (emptyLocales.length) {
      const name = Array.isArray(k.key_name) ? (k.key_name.web || k.key_name.other || JSON.stringify(k.key_name)) : (k.key_name && typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.ios || k.key_name.other) : k.key_name);
      empties[String(name)] = emptyLocales.join(',');
    }
  }
}

return [{ json: {
  project: src.name,
  project_id: src.project_id,
  empty_key_count: Object.keys(empties).length,
  empty_keys: empties
}}];
